def find_solutions():
    solutions = []
    # k = 2^a * 5^b
    for a in range(14):
        for b in range(6):
            k = (2**a) * (5**b)
            if k == 0: continue
            if k % 3 == 2:
                x3 = (k + 400) // 3
                if (k + 400) % 3 == 0:
                    # check if x4 is an integer
                    num = 80 * (k + 400)**2
                    den = 9 * k
                    if num % den == 0:
                        x4 = num // den
                        solutions.append((x3, x4))
    return sorted(list(set(solutions)))

print(find_solutions())
